ac:structured-macro.ac:plain-text-body:
@dataclass
class CenterResult:
    centers_xy: np.ndarray   # (N, 2) float64, [x, y] order
    method: str              # refinement method used (e.g. "logquad")
    backend: str = "cpu"
    meta: dict[str, Any] = {}

@dataclass
class PitchResult:
    values: np.ndarray       # (L,) per-line pitch values
    axis: str                # "row" or "col"
    method: str              # e.g. "per-line"
    backend: str = "cpu"
    meta: dict[str, Any] = {}
    # meta keys: line_centers_perp, line_counts, line_ids_per_point

@dataclass
class ShiftResult:
    shift_yx: np.ndarray          # [y, x] shift (row, column)
    error: float | None = None
    phasediff: float | None = None
    backend: str = "cpu"
    method: str = "phase_xcorr"
    meta: dict[str, Any] = {}

@dataclass
class SpectrumResult:
    frequency: np.ndarray    # spatial frequency in 1/(x units)
    amplitude: np.ndarray    # amplitude in y units
    period: np.ndarray       # spatial period in x units
    method: str = "fft"
    meta: dict[str, Any] = {}

@dataclass
class ComponentStatsResult:
    labels: np.ndarray       # label image (H, W)
    stats: np.ndarray        # per-component stats (N, ...)
    centroids: np.ndarray    # per-component centroids
    num_labels: int
    backend: str = "cpu"
    meta: dict[str, Any] = {}

{
    "initial": {
        "pitch_x": float,           # KNN median x-pitch
        "pitch_y": float,           # KNN median y-pitch
        "dx_candidates": np.ndarray,
        "dy_candidates": np.ndarray,
    },
    "refined": {                    # None if refine=False
        "pitch_x": float,          # refined x-pitch
        "pitch_y": float,          # refined y-pitch
        "kept_count": int,          # number of points used
    }
}

